/**
 * App.tsx — the entry file of the "Story factory" App (the name of this file cannot change).
 *
 * REPO-DESIGN.md §9.1–§9.2. Created by [KIT] 00 A24 (POST /api/v1/apps, then PUT /api/v1/apps/{id}/files with
 * kit/bundle/kit-bundle.json app_files — every draft file is replaced, and App.tsx must be present). Publishing the
 * App and wiring its three endpoints are [BY HAND] (Interfaces → App endpoints), or publishing through Mode 2,
 * whose App tools the MCP docs page does not list yet (VERIFY K18).
 *
 * What it is: the working surface over the tracker for tenants with Records + Apps. It reads sdlc_backlog,
 * sdlc_events and sdlc_milestones and the sdlc_state_machine, kit_catalog and kit_config Resources directly, as the
 * viewer (read-only hooks, lib/tracker.ts). It never writes a Record, runs on no schedule, shows nothing the viewer
 * may not read, and notifies nobody — the kit story does the notifying. Gate decisions deep-link to the tracker Page
 * until K18 confirms that an app endpoint receives the viewer's identity.
 *
 * Git is the system of record (kit/tracker/backlog.yaml); what this App shows is the Records projection as of the
 * last tracker sync. Files: routes/ (one per view), components/ (board, SVG bar chart, timeline), lib/tracker.ts
 * (the only file that touches @tines/apps). Whether nested paths are accepted in PUT …/files is VERIFY K18; if they
 * are not, flatten the tree and update the imports below.
 */
import * as React from "react";
import Backlog from "./routes/Backlog";
import Costs from "./routes/Costs";
import Gates from "./routes/Gates";
import Milestones from "./routes/Milestones";
import StoryDetail from "./routes/StoryDetail";
import { AppRouter, href, useRoutePath, type RouteDef } from "./lib/tracker";

const ROUTES: RouteDef[] = [
  { path: "/", title: "Backlog", element: <Backlog />, inNav: true },
  { path: "/story/:key", title: "Story", element: <StoryDetail />, inNav: false },
  { path: "/gates", title: "Gates", element: <Gates />, inNav: true },
  { path: "/milestones", title: "Milestones", element: <Milestones />, inNav: true },
  { path: "/costs", title: "Costs", element: <Costs />, inNav: true },
];

function Nav() {
  const path = useRoutePath();
  const active = (routePath: string) =>
    routePath === "/" ? path === "/" || path === "" || path.startsWith("/story/") : path.startsWith(routePath);
  return (
    <nav aria-label="Story factory" className="flex gap-1">
      {ROUTES.filter((r) => r.inNav).map((r) => (
        <a
          key={r.path}
          href={href(r.path)}
          aria-current={active(r.path) ? "page" : undefined}
          className={`rounded px-3 py-1.5 text-sm ${
            active(r.path) ? "bg-slate-900 text-white" : "text-slate-700 hover:bg-slate-100"
          }`}
        >
          {r.title}
        </a>
      ))}
    </nav>
  );
}

export default function App() {
  return (
    <div className="min-h-screen bg-white text-slate-900">
      <header className="flex flex-wrap items-center gap-4 border-b border-slate-200 px-4 py-3">
        <h1 className="text-base font-semibold">Story factory</h1>
        <Nav />
      </header>
      <main className="px-4 py-4">
        <AppRouter routes={ROUTES} />
      </main>
      <footer className="border-t border-slate-100 px-4 py-3 text-xs text-slate-500">
        Read-only, as you. Decisions happen at gates — the tracker Page, a PR merge, or a change request — and reach git
        by pull request. Git is the system of record.
      </footer>
    </div>
  );
}

/**
 * components/BarChart.tsx — a grouped bar chart drawn as hand-written SVG.
 *
 * REPO-DESIGN.md §9.2: no chart dependency is assumed (which packages an App may use is VERIFY K18), so the Costs
 * route draws its own bars. Values are plain numbers; a null value is drawn as a hollow "n/a" marker rather than a
 * zero bar, so "not metered" is never mistaken for "free".
 */
import * as React from "react";

export interface BarSeries {
  key: string;
  label: string;
  /** Tailwind fill class for the bars, e.g. "fill-sky-600". */
  fillClass: string;
  /** Tailwind background class for the legend swatch, e.g. "bg-sky-600". */
  swatchClass: string;
}

export interface BarDatum {
  label: string;
  values: Record<string, number | null>;
}

interface BarChartProps {
  title: string;
  data: BarDatum[];
  series: BarSeries[];
  height?: number;
  format?: (value: number) => string;
  emptyText?: string;
}

const PLOT_TOP = 16;
const PLOT_LEFT = 56;
const LABEL_SPACE = 72;

function niceStep(raw: number): number {
  if (raw <= 0) return 1;
  const exponent = Math.floor(Math.log10(raw));
  const fraction = raw / 10 ** exponent;
  const nice = fraction <= 1 ? 1 : fraction <= 2 ? 2 : fraction <= 5 ? 5 : 10;
  return nice * 10 ** exponent;
}

function truncate(text: string, max: number): string {
  return text.length > max ? `${text.slice(0, max - 1)}…` : text;
}

export function BarChart({ title, data, series, height = 280, format = (v) => String(v), emptyText }: BarChartProps) {
  if (data.length === 0) {
    return <p className="text-sm text-slate-500">{emptyText ?? "Nothing to chart yet."}</p>;
  }
  const groupWidth = Math.max(36, series.length * 20 + 16);
  const width = Math.max(360, PLOT_LEFT + data.length * groupWidth + 16);
  const plotBottom = height - LABEL_SPACE;
  const plotHeight = plotBottom - PLOT_TOP;
  const maxValue = Math.max(
    0,
    ...data.flatMap((d) => series.map((s) => (typeof d.values[s.key] === "number" ? (d.values[s.key] as number) : 0))),
  );
  const step = niceStep(maxValue / 4 || 1);
  const top = Math.max(step, Math.ceil(maxValue / step) * step);
  const ticks: number[] = [];
  for (let t = 0; t <= top + step / 2; t += step) ticks.push(t);
  const y = (value: number) => plotBottom - (value / top) * plotHeight;
  const barWidth = Math.min(22, (groupWidth - 12) / series.length);

  return (
    <figure className="w-full">
      <div className="overflow-x-auto">
        <svg
          role="img"
          aria-label={title}
          viewBox={`0 0 ${width} ${height}`}
          width={width}
          height={height}
          className="max-w-none"
        >
          <title>{title}</title>
          {ticks.map((t) => (
            <g key={`tick-${t}`}>
              <line x1={PLOT_LEFT} x2={width - 8} y1={y(t)} y2={y(t)} className="stroke-slate-200" strokeWidth={1} />
              <text x={PLOT_LEFT - 6} y={y(t) + 3} textAnchor="end" className="fill-slate-500" fontSize={10}>
                {format(t)}
              </text>
            </g>
          ))}
          <line x1={PLOT_LEFT} x2={width - 8} y1={plotBottom} y2={plotBottom} className="stroke-slate-400" strokeWidth={1} />
          {data.map((d, i) => {
            const groupX = PLOT_LEFT + i * groupWidth + (groupWidth - barWidth * series.length) / 2;
            const labelX = groupX + (barWidth * series.length) / 2;
            return (
              <g key={`group-${d.label}-${i}`}>
                {series.map((s, j) => {
                  const value = d.values[s.key];
                  const x = groupX + j * barWidth;
                  if (typeof value !== "number") {
                    return (
                      <g key={s.key}>
                        <rect
                          x={x + 1}
                          y={plotBottom - 10}
                          width={barWidth - 2}
                          height={10}
                          className="fill-none stroke-slate-400"
                          strokeDasharray="2 2"
                        />
                        <title>{`${d.label} · ${s.label}: n/a`}</title>
                      </g>
                    );
                  }
                  const barHeight = Math.max(value > 0 ? 1 : 0, plotBottom - y(value));
                  return (
                    <rect
                      key={s.key}
                      x={x + 1}
                      y={plotBottom - barHeight}
                      width={barWidth - 2}
                      height={barHeight}
                      className={s.fillClass}
                    >
                      <title>{`${d.label} · ${s.label}: ${format(value)}`}</title>
                    </rect>
                  );
                })}
                <text
                  x={labelX}
                  y={plotBottom + 12}
                  textAnchor="end"
                  transform={`rotate(-35 ${labelX} ${plotBottom + 12})`}
                  className="fill-slate-600"
                  fontSize={10}
                >
                  {truncate(d.label, 24)}
                </text>
              </g>
            );
          })}
        </svg>
      </div>
      <figcaption className="mt-2 flex flex-wrap gap-4 text-xs text-slate-600">
        {series.map((s) => (
          <span key={s.key} className="inline-flex items-center gap-1">
            <span className={`inline-block h-3 w-3 rounded-sm ${s.swatchClass}`} aria-hidden="true" />
            {s.label}
          </span>
        ))}
        <span className="inline-flex items-center gap-1">
          <span className="inline-block h-3 w-3 rounded-sm border border-dashed border-slate-400" aria-hidden="true" />
          n/a (not metered, or not reported yet)
        </span>
      </figcaption>
    </figure>
  );
}

export default BarChart;

/**
 * components/PhaseBoard.tsx — one column per phase, one card per story (REPO-DESIGN.md §9.2, the Backlog route).
 *
 * Each card shows key · title · mode badge · owner · target date · open gate, and links to the story's detail
 * route. The eight lifecycle phases are always shown in order; the holding and terminal columns (parked,
 * rejected, retired) appear only when a story is in them. Read-only: the board never moves a card — a phase
 * changes only through a gate (a Page decision, a merge, a change request) and reaches git by PR.
 */
import * as React from "react";
import { href, formatDate, MODE_LABELS, type BacklogRow } from "../lib/tracker";

const ALWAYS_SHOWN = ["intake", "discover", "design", "build", "verify", "ship", "operate", "improve"];

interface PhaseBoardProps {
  phases: string[];
  rows: BacklogRow[];
}

function GateBadge({ gate }: { gate: string }) {
  if (!gate || gate === "none") return null;
  return (
    <span className="rounded bg-amber-100 px-1.5 py-0.5 text-[11px] font-medium text-amber-900" title="open gate">
      {gate}
    </span>
  );
}

function ModeBadge({ mode }: { mode: string }) {
  return (
    <span className="rounded bg-slate-100 px-1.5 py-0.5 text-[11px] text-slate-700" title="mode badge">
      {MODE_LABELS[mode] ?? mode}
    </span>
  );
}

function StoryCard({ row }: { row: BacklogRow }) {
  return (
    <li>
      <a
        href={href(`/story/${encodeURIComponent(row.story_key)}`)}
        className="block rounded-md border border-slate-200 bg-white p-2 shadow-sm hover:border-sky-400 focus:outline-none focus:ring-2 focus:ring-sky-400"
      >
        <div className="flex items-start justify-between gap-2">
          <span className="font-mono text-[11px] text-slate-500">{row.story_key}</span>
          <GateBadge gate={row.open_gate} />
        </div>
        <div className="mt-1 text-sm font-medium leading-snug text-slate-900">{row.title || row.story_key}</div>
        <div className="mt-2 flex flex-wrap items-center gap-1.5 text-[11px] text-slate-600">
          <ModeBadge mode={row.mode} />
          <span title="owner (a role)">{row.owner || "unassigned"}</span>
          <span aria-hidden="true">·</span>
          <span title="target date (UTC)">{formatDate(row.target_date)}</span>
          {row.status && row.status !== "active" ? (
            <span className="rounded bg-violet-100 px-1.5 py-0.5 text-violet-900" title="status">
              {row.status}
            </span>
          ) : null}
          {row.pending_repo_sync ? (
            <span
              className="rounded bg-sky-100 px-1.5 py-0.5 text-sky-900"
              title="A Tines-side change is waiting for its tracker PR to merge; it is provisional until then."
            >
              provisional
            </span>
          ) : null}
        </div>
      </a>
    </li>
  );
}

export function PhaseBoard({ phases, rows }: PhaseBoardProps) {
  const grouped = React.useMemo(() => {
    const map = new Map<string, BacklogRow[]>();
    for (const phase of phases) map.set(phase, []);
    for (const row of rows) {
      if (!map.has(row.phase)) map.set(row.phase, []);
      map.get(row.phase)?.push(row);
    }
    for (const list of map.values()) list.sort((a, b) => a.story_key.localeCompare(b.story_key));
    return map;
  }, [phases, rows]);

  const columns = Array.from(grouped.keys()).filter(
    (phase) => ALWAYS_SHOWN.includes(phase) || (grouped.get(phase)?.length ?? 0) > 0,
  );

  return (
    <div className="flex gap-3 overflow-x-auto pb-2" role="list" aria-label="Stories by phase">
      {columns.map((phase) => {
        const list = grouped.get(phase) ?? [];
        return (
          <section key={phase} role="listitem" className="w-64 shrink-0 rounded-lg bg-slate-50 p-2" aria-label={phase}>
            <header className="mb-2 flex items-center justify-between px-1">
              <h3 className="text-xs font-semibold uppercase tracking-wide text-slate-600">{phase}</h3>
              <span className="rounded-full bg-white px-2 text-xs text-slate-500">{list.length}</span>
            </header>
            {list.length === 0 ? (
              <p className="px-1 text-xs text-slate-400">—</p>
            ) : (
              <ul className="space-y-2">
                {list.map((row) => (
                  <StoryCard key={row.story_key} row={row} />
                ))}
              </ul>
            )}
          </section>
        );
      })}
    </div>
  );
}

export default PhaseBoard;

/**
 * components/Timeline.tsx — a story's transition timeline from its sdlc_events rows (REPO-DESIGN.md §9.2,
 * the Story detail route).
 *
 * The events are the append-only audit trail (§6.5): transitions, gate decisions, specialist runs, syncs,
 * conflicts, budget parks and escalations. The actor is always a role; the in-tenant `actor_ref` (an approver's
 * email) is never rendered. Summaries are shown as plain text: event text is data, never markup.
 */
import * as React from "react";
import { formatDate, type EventRow } from "../lib/tracker";

const TYPE_STYLES: Record<string, string> = {
  transition: "bg-sky-500",
  gate_decision: "bg-emerald-500",
  specialist_run: "bg-violet-500",
  sync: "bg-slate-400",
  conflict: "bg-amber-500",
  budget: "bg-orange-500",
  escalation: "bg-rose-500",
};

function headline(e: EventRow): string {
  const move = e.from_phase !== "none" || e.to_phase !== "none" ? `${e.from_phase} → ${e.to_phase}` : "";
  switch (e.event_type) {
    case "transition":
      return `${move}${e.decision ? ` (${e.decision})` : ""}`;
    case "gate_decision":
      return `${e.gate}: ${e.decision}${move ? ` · ${move}` : ""}`;
    case "specialist_run":
      return `${e.agent || "specialist"} ${e.decision || "ran"}`;
    case "budget":
      return `budget ${e.decision || "park"}${move ? ` · ${move}` : ""}`;
    case "escalation":
      return `escalation${e.gate !== "none" ? ` (${e.gate})` : ""}`;
    case "conflict":
      return `conflict${e.decision ? `: ${e.decision}` : ""}`;
    default:
      return e.event_type;
  }
}

export function Timeline({ events }: { events: EventRow[] }) {
  if (events.length === 0) {
    return (
      <p className="text-sm text-slate-500">
        No events yet. Transitions arrive through the tracker sync after each merge to main; Tines-side decisions
        appear here as soon as they are made.
      </p>
    );
  }
  return (
    <ol className="relative ml-2 border-l border-slate-200">
      {events.map((e) => (
        <li key={e.recordId} className="mb-4 ml-4">
          <span
            className={`absolute -left-1.5 mt-1.5 h-3 w-3 rounded-full ring-2 ring-white ${TYPE_STYLES[e.event_type] ?? "bg-slate-300"}`}
            aria-hidden="true"
          />
          <div className="text-xs text-slate-500">
            {formatDate(e.created_at)} · {e.actor || "—"} <span className="text-slate-400">({e.actor_kind || "?"})</span>
            {e.tracker_rev !== null ? <span className="text-slate-400"> · rev {e.tracker_rev}</span> : null}
          </div>
          <div className="text-sm font-medium text-slate-900">{headline(e)}</div>
          {e.summary ? <p className="mt-0.5 whitespace-pre-wrap text-sm text-slate-700">{e.summary}</p> : null}
          {e.event_type === "specialist_run" && (e.model || e.credits_used !== null) ? (
            <p className="mt-0.5 text-xs text-slate-500">
              {e.model ? `model ${e.model}` : "model not reported"}
              {e.credits_used !== null ? ` · ${e.credits_used} credits` : ""}
              {e.input_tokens !== null ? ` · ${e.input_tokens} in / ${e.output_tokens ?? 0} out tokens` : ""}
            </p>
          ) : null}
          {e.ref ? <p className="mt-0.5 font-mono text-[11px] text-slate-500">{e.ref}</p> : null}
        </li>
      ))}
    </ol>
  );
}

export default Timeline;

/**
 * lib/tracker.ts — the ONLY file in the App that touches `@tines/apps`.
 *
 * REPO-DESIGN.md §9.2. The App is React 19 + Tailwind in a sandboxed iframe, with App.tsx as the entry and routes
 * through TinesRouter. It reads Records and Resources DIRECTLY through the read-only `@tines/apps` hooks —
 * `useRecords` (20 per page by default, 500 max), `useRecordsQuery` (up to 1,000 rows per query), `useResource`
 * (and `useCase`, unused here) — which run AS THE VIEWER, with the viewer's own permissions. Writes and external
 * calls go only through app endpoints (a Webhook entry + a message-only Event Transform exit in [KIT] 00 section C;
 * see ../endpoints.md). Sandbox: no network calls from app code, no localStorage or cookies, no
 * crypto.randomUUID, no embedding outside Tines, no anonymous access.
 *
 * VERIFY K18. The design's sources name the hooks and TinesRouter; they do not give their argument or result
 * shapes, whether nested file paths are accepted, or the primitive an App uses to call an app endpoint. Every
 * line below that assumes one of those is marked "VERIFY K18". When K18 is resolved, change ONLY this file: the
 * routes and components receive plain typed rows (BacklogRow, EventRow, MilestoneRow) and never see a platform
 * object. Record fields are read by the names in kit/records/*.record-type.json (kit/tracker/field-map.yaml).
 */
import * as React from "react";
import * as TinesApps from "@tines/apps"; // VERIFY K18: the package name and its exports, as REPO-DESIGN.md §9.2 names them
import { useRecords, useRecordsQuery, useResource } from "@tines/apps"; // VERIFY K18: argument and result shapes

// ─── Record types, Resources and Pages the App reads ────────────────────────────────────────────────────────────

export const RECORD_TYPES = {
  backlog: "sdlc_backlog",
  events: "sdlc_events",
  milestones: "sdlc_milestones",
} as const;

export const RESOURCES = {
  stateMachine: "sdlc_state_machine",
  catalog: "kit_catalog",
  config: "kit_config",
} as const;

/** The tracker_home root Page's URL identifier (stories/kit-factory/pages/tracker-home.md). Mid-story Pages
 * (gate_decision, add_use_case) have per-run URLs, so the App links to this root Page instead. Whether the
 * identifier survives story import is VERIFY K8. */
export const TRACKER_HOME_PAGE = "story-factory-tracker";

export const TINES_SIDE_GATES = ["G0", "G6", "G7", "GX"] as const; // decided on the gate_decision Page (§7.8)

// ─── Plain row types ─────────────────────────────────────────────────────────────────────────────────────────────

export interface BacklogRow {
  recordId: string;
  story_key: string;
  title: string;
  use_case: string;
  library_seed_id: number | null;
  mode: string;
  owner: string;
  tier: string;
  phase: string;
  status: string;
  open_gate: string;
  attempt: number;
  target_date: string | null;
  credit_estimate_monthly: number | null;
  credit_estimate_basis: string;
  provider: string;
  prod_story_id: number | null;
  live_since: string | null;
  design_pr: string;
  build_pr: string;
  change_request_id: string;
  rev: number;
  pending_repo_sync: boolean;
  specialist_due: string;
  specialist_status: string;
  proposal: unknown;
  brief: string;
  retro: string;
  last_actor: string;
  last_transition_at: string | null;
}

export interface EventRow {
  recordId: string;
  created_at: string | null;
  story_key: string;
  event_type: string;
  from_phase: string;
  to_phase: string;
  gate: string;
  decision: string;
  actor: string; // a role; actor_ref (the approver's email) is never rendered
  actor_kind: string;
  agent: string;
  model: string;
  credits_used: number | null;
  input_tokens: number | null;
  output_tokens: number | null;
  summary: string;
  ref: string;
  tracker_rev: number | null;
}

export interface MilestoneRow {
  recordId: string;
  milestone_id: string;
  title: string;
  criteria: string[];
  status: string;
  due_date: string | null;
  evidence_ref: string;
  owner: string;
  pending_repo_sync: boolean;
}

/** The parts of the sdlc_state_machine Resource the App reads (kit/resources/sdlc_state_machine.example.json). */
export interface StateMachine {
  phases: string[];
  all_phases: string[];
  gates: string[];
  gate_decided_by: Record<string, string>;
  gate_types: Record<string, string>;
  page_gates: string[];
  enums: Record<string, string[]>;
}

/** The parts of the kit_config Resource the App reads (kit/resources/kit_config.example.json). */
export interface KitConfig {
  tenant_host?: string;
  entitlements?: Record<string, boolean>;
  llm?: { choice?: string; provider_name?: string };
}

/** The parts of the kit_catalog Resource the App reads (kit/resources/kit_catalog.example.json). */
export interface KitCatalog {
  library_seeds: { id: number; name: string; reference_only: boolean }[];
}

export interface Loaded<T> {
  rows: T[];
  loading: boolean;
  error: string | null;
}

export interface LoadedValue<T> {
  value: T | null;
  loading: boolean;
  error: string | null;
}

// ─── Coercion helpers (Records return TEXT/NUMBER/TIMESTAMP/BOOLEAN/TEXT_ENUM/JSON/ARTIFACT values) ────────────

const str = (v: unknown): string => (v === null || v === undefined ? "" : String(v));
const num = (v: unknown): number | null => {
  if (v === null || v === undefined || v === "") return null;
  const n = typeof v === "number" ? v : Number(v);
  return Number.isFinite(n) ? n : null;
};
const bool = (v: unknown): boolean => v === true || v === "true";
const ts = (v: unknown): string | null => (v ? String(v) : null);
const enumValue = (v: unknown): string => (v === null || v === undefined || v === "" ? "none" : String(v));

/**
 * VERIFY K18: the shape of one record as the hooks return it. Accepted, in order: a map under `fields`, a map
 * under `field_values`, an array of `{ name, value }` under either key, or the field names at the top level.
 */
function fieldsOf(record: unknown): Record<string, unknown> {
  if (!record || typeof record !== "object") return {};
  const r = record as Record<string, unknown>;
  for (const key of ["fields", "field_values", "values"]) {
    const inner = r[key];
    if (Array.isArray(inner)) {
      const out: Record<string, unknown> = {};
      for (const item of inner) {
        if (item && typeof item === "object") {
          const entry = item as Record<string, unknown>;
          const name = str(entry.name ?? entry.field_name ?? entry.key);
          if (name) out[name] = entry.value;
        }
      }
      return { ...r, ...out };
    }
    if (inner && typeof inner === "object") return { ...r, ...(inner as Record<string, unknown>) };
  }
  return r;
}

const recordIdOf = (f: Record<string, unknown>, index: number): string => str(f.id ?? f.record_id ?? f.story_key ?? index);

/** VERIFY K18: the hook result. Accepted: an array, or an object carrying the rows under records / data / rows. */
function resultRows(result: unknown): unknown[] {
  if (Array.isArray(result)) return result;
  if (result && typeof result === "object") {
    const r = result as Record<string, unknown>;
    for (const key of ["records", "data", "rows", "items"]) {
      if (Array.isArray(r[key])) return r[key] as unknown[];
    }
  }
  return [];
}

function resultState(result: unknown): { loading: boolean; error: string | null } {
  if (!result || typeof result !== "object" || Array.isArray(result)) return { loading: false, error: null };
  const r = result as Record<string, unknown>;
  const loading = Boolean(r.isLoading ?? r.loading ?? false);
  const err = r.error;
  return { loading, error: err ? str((err as { message?: unknown }).message ?? err) : null };
}

/** VERIFY K18: a Resource hook result. Accepted: `{ value }`, `{ data }`, or the value itself. */
function resourceValue<T>(result: unknown): T | null {
  if (result === null || result === undefined) return null;
  if (typeof result === "object" && !Array.isArray(result)) {
    const r = result as Record<string, unknown>;
    if ("value" in r) return (typeof r.value === "string" ? safeJson(r.value) : r.value) as T;
    if ("data" in r) return r.data as T;
  }
  return (typeof result === "string" ? safeJson(result) : result) as T;
}

function safeJson(text: string): unknown {
  try {
    return JSON.parse(text);
  } catch {
    return null;
  }
}

function toBacklogRow(record: unknown, index: number): BacklogRow {
  const f = fieldsOf(record);
  return {
    recordId: recordIdOf(f, index),
    story_key: str(f.story_key),
    title: str(f.title),
    use_case: str(f.use_case),
    library_seed_id: num(f.library_seed_id),
    mode: enumValue(f.mode),
