/**
 * routes/Backlog.tsx — the board: one column per phase, filters by owner, tier and mode, and the intake form.
 *
 * REPO-DESIGN.md §9.2 row "Backlog": data = useRecords(sdlc_backlog); phase names from
 * useResource(sdlc_state_machine). Adding a use case is a write, so it goes through the app_add_use_case endpoint
 * (../endpoints.md), which runs the same chain as the add_use_case Page (C4). Until the App's endpoint call is
 * wired (VERIFY K18), the form says so and links to the tracker Page, where "Add a use case" does the same thing.
 * A new row is provisional until its tracker PR merges (Flow 2).
 */
import * as React from "react";
import { PhaseBoard } from "../components/PhaseBoard";
import {
  callAppEndpoint,
  MODE_LABELS,
  pageLink,
  phaseOrder,
  useBacklog,
  useCatalog,
  useKitConfig,
  useStateMachine,
  type KitCatalog,
  type KitConfig,
} from "../lib/tracker";

const ALL = "all";
const MODE_HINTS = ["none", "sub-story", "mode-1-preset", "mode-3-agent", "mode-4-server", "unknown"];
const TOKEN_LIKE = /(ghp_|github_pat_|gho_|ghs_|xox[bp]-|sk-|AKIA|Bearer\s)/;

function Select({ label, value, options, onChange }: { label: string; value: string; options: string[]; onChange: (v: string) => void }) {
  return (
    <label className="flex flex-col text-xs text-slate-600">
      {label}
      <select
        className="mt-1 rounded border border-slate-300 bg-white px-2 py-1 text-sm text-slate-900"
        value={value}
        onChange={(e) => onChange(e.target.value)}
      >
        <option value={ALL}>all</option>
        {options.map((o) => (
          <option key={o} value={o}>
            {MODE_LABELS[o] && label === "Mode" ? MODE_LABELS[o] : o}
          </option>
        ))}
      </select>
    </label>
  );
}

function AddUseCase({ config, catalog }: { config: KitConfig | null; catalog: KitCatalog | null }) {
  const [open, setOpen] = React.useState(false);
  const [title, setTitle] = React.useState("");
  const [useCase, setUseCase] = React.useState("");
  const [owner, setOwner] = React.useState("");
  const [targetDate, setTargetDate] = React.useState("");
  const [seed, setSeed] = React.useState("none");
  const [modeHint, setModeHint] = React.useState("unknown");
  const [message, setMessage] = React.useState<string | null>(null);
  const [busy, setBusy] = React.useState(false);
  const trackerPage = pageLink(config);

  const problems: string[] = [];
  if (!title.trim()) problems.push("a title");
  if (!useCase.trim()) problems.push("the use case");
  if (!owner.trim() || owner.includes("@")) problems.push("an owner role (a role, never a person or an email)");
  const tokenLike = TOKEN_LIKE.test(`${title} ${useCase} ${owner}`);

  async function submit(event: React.FormEvent) {
    event.preventDefault();
    if (problems.length || tokenLike) return;
    setBusy(true);
    const result = await callAppEndpoint("app_add_use_case", {
      title: title.trim(),
      use_case: useCase.trim(),
      owner_role: owner.trim(),
      target_date: targetDate ? `${targetDate}T00:00:00Z` : "",
      library_seed_id: seed === "none" ? null : Number(seed),
      mode_hint: modeHint,
    });
    setBusy(false);
    setMessage(
      result.ok
        ? "Added in intake. The brief writer drafts the intake brief, and the row reaches git with the next tracker PR."
        : result.message,
    );
  }

  return (
    <section className="mt-6 rounded-lg border border-slate-200 p-3">
      <button
        type="button"
        className="text-sm font-medium text-sky-700 hover:underline"
        onClick={() => setOpen((v) => !v)}
        aria-expanded={open}
      >
        {open ? "Hide" : "Add a use case"}
      </button>
      {open ? (
        <form className="mt-3 grid gap-3 md:grid-cols-2" onSubmit={submit}>
          <label className="flex flex-col text-xs text-slate-600">
            Title
            <input className="mt-1 rounded border border-slate-300 px-2 py-1 text-sm" value={title} onChange={(e) => setTitle(e.target.value)} />
          </label>
          <label className="flex flex-col text-xs text-slate-600">
            Owner role
            <input className="mt-1 rounded border border-slate-300 px-2 py-1 text-sm" value={owner} onChange={(e) => setOwner(e.target.value)} placeholder="security-automation" />
          </label>
          <label className="flex flex-col text-xs text-slate-600 md:col-span-2">
            Use case (what happens today, what should happen)
            <textarea className="mt-1 h-24 rounded border border-slate-300 px-2 py-1 text-sm" value={useCase} onChange={(e) => setUseCase(e.target.value)} />
          </label>
          <label className="flex flex-col text-xs text-slate-600">
            Target date (UTC)
            <input type="date" className="mt-1 rounded border border-slate-300 px-2 py-1 text-sm" value={targetDate} onChange={(e) => setTargetDate(e.target.value)} />
          </label>
          <label className="flex flex-col text-xs text-slate-600">
            Library seed (verified catalog ids only)
            <select className="mt-1 rounded border border-slate-300 bg-white px-2 py-1 text-sm" value={seed} onChange={(e) => setSeed(e.target.value)}>
              <option value="none">none</option>
              {(catalog?.library_seeds ?? [])
                .filter((s) => !s.reference_only)
                .map((s) => (
                  <option key={s.id} value={String(s.id)}>
                    {s.id} · {s.name}
                  </option>
                ))}
            </select>
          </label>
          <label className="flex flex-col text-xs text-slate-600">
            Mode hint
            <select className="mt-1 rounded border border-slate-300 bg-white px-2 py-1 text-sm" value={modeHint} onChange={(e) => setModeHint(e.target.value)}>
              {MODE_HINTS.map((m) => (
                <option key={m} value={m}>
                  {m}
                </option>
              ))}
            </select>
          </label>
          <div className="flex flex-col justify-end gap-1 text-xs text-slate-600 md:col-span-2">
            {tokenLike ? (
              <p className="text-rose-700">That looks like a token. Never paste a token, key or password here.</p>
            ) : null}
            {problems.length ? <p>Still needed: {problems.join(", ")}.</p> : null}
            <button
              type="submit"
              disabled={busy || problems.length > 0 || tokenLike}
              className="w-fit rounded bg-sky-700 px-3 py-1.5 text-sm font-medium text-white disabled:opacity-40"
            >
              {busy ? "Adding…" : "Add in intake"}
            </button>
            {message ? (
              <p className="text-slate-700">
                {message}{" "}
                {trackerPage ? (
                  <a className="text-sky-700 underline" href={trackerPage} target="_blank" rel="noreferrer">
                    Open the tracker Page → Add a use case
                  </a>
                ) : null}
              </p>
            ) : null}
          </div>
        </form>
      ) : null}
    </section>
  );
}

export default function Backlog() {
  const backlog = useBacklog();
  const sm = useStateMachine();
  const config = useKitConfig();
  const catalog = useCatalog();
  const [owner, setOwner] = React.useState(ALL);
  const [tier, setTier] = React.useState(ALL);
  const [mode, setMode] = React.useState(ALL);

  const unique = (values: string[]) => Array.from(new Set(values.filter(Boolean))).sort();
  const owners = unique(backlog.rows.map((r) => r.owner));
  const tiers = unique(backlog.rows.map((r) => r.tier));
  const modes = sm.value?.enums?.mode ?? unique(backlog.rows.map((r) => r.mode));
  const rows = backlog.rows.filter(
    (r) => (owner === ALL || r.owner === owner) && (tier === ALL || r.tier === tier) && (mode === ALL || r.mode === mode),
  );

  return (
    <div>
      <div className="mb-4 flex flex-wrap items-end gap-3">
        <h2 className="mr-auto text-lg font-semibold">Backlog</h2>
        <Select label="Owner" value={owner} options={owners} onChange={setOwner} />
        <Select label="Tier" value={tier} options={tiers} onChange={setTier} />
        <Select label="Mode" value={mode} options={modes} onChange={setMode} />
      </div>
      {backlog.error ? (
        <p className="mb-3 rounded bg-rose-50 p-2 text-sm text-rose-800">
          The backlog could not be read: {backlog.error}. The App reads as you; ask for access to the ops team, or
          open the tracker in git (kit/tracker/backlog.yaml).
        </p>
      ) : null}
      {backlog.loading ? <p className="text-sm text-slate-500">Loading the backlog…</p> : null}
      <PhaseBoard phases={phaseOrder(sm.value)} rows={rows} />
      <p className="mt-2 text-xs text-slate-500">
        {rows.length} of {backlog.rows.length} stories. Git is the system of record; this board is the Records
        projection, current as of the last tracker sync.
      </p>
      <AddUseCase config={config.value} catalog={catalog.value} />
    </div>
  );
}

/**
 * routes/Costs.tsx — monthly credit estimate vs actual, per story.
 *
 * REPO-DESIGN.md §9.2 row "Costs": estimates from Records (sdlc_backlog.credit_estimate_monthly, set at design from
 * credits observed in dev); actuals from the app_costs endpoint → GET /api/v1/ai_usage?group_by=story with the
 * tines_api_readonly key, which sees only what that key may see (K38). The chart is hand-written SVG (no chart
 * dependency is assumed, K18). Until the App's endpoint call is wired (K18), actuals show as "n/a" and the Tines
 * Dashboard and drift.yml's budget job are the places to read them.
 *
 * Credits and billed cost are never summed: a story on a custom or local provider spends no Tines AI credits and
 * bills outside Tines (`billed_cost`, which for custom and local providers is K25), so it shows "not metered in
 * credits". 1 credit = $0.01 on Tines-provided models.
 */
import * as React from "react";
import { BarChart, type BarDatum, type BarSeries } from "../components/BarChart";
import { formatCredits, href, useBacklog, useCostActuals } from "../lib/tracker";

const SERIES: BarSeries[] = [
  { key: "estimate", label: "Monthly estimate (credits)", fillClass: "fill-slate-400", swatchClass: "bg-slate-400" },
  { key: "actual", label: "Used this month (credits)", fillClass: "fill-sky-600", swatchClass: "bg-sky-600" },
];

export default function Costs() {
  const backlog = useBacklog();
  const actuals = useCostActuals();
  const actualByStoryId = new Map<number, number | null>();
  const actualByKey = new Map<string, number | null>();
  for (const a of actuals.rows) {
    if (a.story_id !== null) actualByStoryId.set(a.story_id, a.credits_used);
    if (a.story_key) actualByKey.set(a.story_key, a.credits_used);
  }
  const rows = backlog.rows.filter((r) => r.phase !== "rejected");
  const actualFor = (key: string, prodId: number | null): number | null =>
    actualByKey.get(key) ?? (prodId ? actualByStoryId.get(prodId) ?? null : null);

  const data: BarDatum[] = rows
    .filter((r) => r.credit_estimate_monthly !== 0 || actualFor(r.story_key, r.prod_story_id))
    .map((r) => ({
      label: r.story_key,
      values: {
        estimate: r.credit_estimate_monthly,
        actual: r.provider === "custom" || r.provider === "local" ? null : actualFor(r.story_key, r.prod_story_id),
      },
    }));

  return (
    <div>
      <h2 className="mb-1 text-lg font-semibold">Credits: estimate vs actual</h2>
      <p className="mb-4 text-sm text-slate-600">
        Stories with no AI Agent action, Workbench or Workbench for Storyboard use no credits and are left out of the
        chart. An improve trigger fires at 1.5 × the estimate.
      </p>
      {actuals.message ? <p className="mb-3 rounded bg-amber-50 p-2 text-xs text-amber-900">{actuals.message}</p> : null}
      <BarChart
        title="Monthly credit estimate and credits used, per story"
        data={data}
        series={SERIES}
        format={(v) => `${Math.round(v)}`}
        emptyText="No story has a credit estimate yet — estimates are set at design from credits observed in dev."
      />
      <table className="mt-6 w-full text-left text-sm">
        <thead className="text-xs text-slate-500">
          <tr>
            <th className="py-1 pr-3 font-medium">Story</th>
            <th className="py-1 pr-3 font-medium">Provider</th>
            <th className="py-1 pr-3 font-medium">Estimate</th>
            <th className="py-1 pr-3 font-medium">Used this month</th>
            <th className="py-1 font-medium">Basis</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((r) => {
            const external = r.provider === "custom" || r.provider === "local";
            const used = actualFor(r.story_key, r.prod_story_id);
            const ratio = !external && used !== null && r.credit_estimate_monthly ? used / r.credit_estimate_monthly : null;
            return (
              <tr key={r.story_key} className="border-t border-slate-100">
                <td className="py-1.5 pr-3">
                  <a className="text-sky-700 underline" href={href(`/story/${encodeURIComponent(r.story_key)}`)}>
                    {r.story_key}
                  </a>
                </td>
                <td className="py-1.5 pr-3 text-slate-700">{r.provider}</td>
                <td className="py-1.5 pr-3 text-slate-700">{formatCredits(r.credit_estimate_monthly)}</td>
                <td className={`py-1.5 pr-3 ${ratio !== null && ratio >= 1.5 ? "font-medium text-rose-700" : "text-slate-700"}`}>
                  {external ? "not metered in credits (billed_cost)" : used === null ? "n/a" : `${Math.round(used)} cr`}
                  {ratio !== null && ratio >= 1.5 ? " · ≥ 1.5 × estimate" : ""}
                </td>
                <td className="py-1.5 text-xs text-slate-500">{r.credit_estimate_basis || "—"}</td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

/**
 * routes/Gates.tsx — every open gate, who decides it, and where.
 *
 * REPO-DESIGN.md §9.2 row "Gates": data = useRecords(sdlc_backlog, open_gate ≠ none) — filtered here as well, so
 * the view is right whatever filter syntax the hook accepts (VERIFY K18). Each gate has ONE instrument (§4.5 rule 3):
 *   G0, G6, G7, GX and the GB release (unpark) → the gate_decision Page. "Decide" deep-links to the tracker Page
 *     ("Decide a gate") until K18 confirms that an app endpoint receives the viewer's identity; the Page checks the
 *     submitter's email against the sdlc_approvers Resource on every decision.
 *   G1 → ./scripts/sdlc ready on the design PR · G2 → the merge of the design PR · G3 → /sdlc-gate in the build
 *   session · G4 → the merge of the build PR · G5a → the GitHub production environment's required reviewer ·
 *   G5b → the change request in Tines, approved and pushed by a named approver.
 */
import * as React from "react";
import {
  href,
  pageLink,
  TINES_SIDE_GATES,
  useBacklog,
  useKitConfig,
  useStateMachine,
  type BacklogRow,
  type KitConfig,
} from "../lib/tracker";

const INSTRUMENT: Record<string, string> = {
  G0: "the gate_decision Page",
  G1: "./scripts/sdlc ready — the sdlc check on the design PR",
  G2: "the merge of the design PR (a CODEOWNER who is not the author)",
  G3: "/sdlc-gate <slug> G3 approve — in the build session",
  G4: "the merge of the build PR (CI green, QA verification line, a CODEOWNER, a human merge)",
  G5a: "the GitHub production environment's required reviewer releases ship.yml's first import",
  G5b: "the change request in Tines — a named approver approves and pushes",
  G6: "the gate_decision Page",
  G7: "the gate_decision Page",
  GB: "the gate_decision Page (unpark)",
  GX: "the gate_decision Page",
};

function Action({ row, config }: { row: BacklogRow; config: KitConfig | null }) {
  const gate = row.phase === "parked" && row.open_gate === "none" ? "GB" : row.open_gate;
  const trackerPage = pageLink(config);
  if ((TINES_SIDE_GATES as readonly string[]).includes(gate) || gate === "GB") {
    return trackerPage ? (
      <a
        className="rounded bg-sky-700 px-2 py-1 text-xs font-medium text-white hover:bg-sky-800"
        href={trackerPage}
        target="_blank"
        rel="noreferrer"
        title="Opens the tracker Page; choose Decide a gate. Your email is checked against the approvers list."
      >
        Decide on the tracker Page
      </a>
    ) : (
      <span className="text-xs text-slate-500">Open the tracker_home Page and choose Decide a gate</span>
    );
  }
  const pr = gate === "G2" ? row.design_pr : gate === "G4" ? row.build_pr : "";
  if (pr.startsWith("https://github.com/")) {
    return (
      <a className="text-xs text-sky-700 underline" href={pr} target="_blank" rel="noreferrer">
        Open the PR
      </a>
    );
  }
  if (gate === "G5b" && row.change_request_id) {
    return <span className="font-mono text-xs">change request {row.change_request_id}</span>;
  }
  return <span className="text-xs text-slate-500">decided outside the App</span>;
}

export default function Gates() {
  const backlog = useBacklog();
  const sm = useStateMachine();
  const config = useKitConfig();
  const open = backlog.rows.filter((r) => r.open_gate !== "none" || r.phase === "parked");
  const byGate = new Map<string, BacklogRow[]>();
  for (const row of open) {
    const gate = row.open_gate !== "none" ? row.open_gate : "GB";
    if (!byGate.has(gate)) byGate.set(gate, []);
    byGate.get(gate)?.push(row);
  }
  const order = sm.value?.gates ?? ["G0", "G1", "G2", "G3", "G4", "G5a", "G5b", "G6", "G7", "GB", "GX"];
  const gates = Array.from(byGate.keys()).sort((a, b) => order.indexOf(a) - order.indexOf(b));

  return (
    <div>
      <h2 className="mb-1 text-lg font-semibold">Open gates</h2>
      <p className="mb-4 text-sm text-slate-600">
        One open gate per story. Authority comes from versioned files and the approvers Resource, never from a chat
        reply. A decision made on the Page is provisional until its tracker PR merges.
      </p>
      {backlog.loading ? <p className="text-sm text-slate-500">Loading…</p> : null}
      {gates.length === 0 && !backlog.loading ? <p className="text-sm text-slate-500">No gate is open.</p> : null}
      <div className="space-y-5">
        {gates.map((gate) => (
          <section key={gate}>
            <h3 className="text-sm font-semibold">
              {gate} <span className="font-normal text-slate-500">— decided by {sm.value?.gate_decided_by?.[gate] ?? "see sdlc/gates/README.md"}</span>
            </h3>
            <p className="mb-2 text-xs text-slate-500">Instrument: {INSTRUMENT[gate] ?? "see sdlc/gates/README.md"}</p>
            <table className="w-full text-left text-sm">
              <thead className="text-xs text-slate-500">
                <tr>
                  <th className="py-1 pr-3 font-medium">Story</th>
                  <th className="py-1 pr-3 font-medium">Phase / status</th>
                  <th className="py-1 pr-3 font-medium">Owner</th>
                  <th className="py-1 font-medium">Where to decide</th>
                </tr>
              </thead>
              <tbody>
                {(byGate.get(gate) ?? []).map((row) => (
                  <tr key={row.story_key} className="border-t border-slate-100">
                    <td className="py-1.5 pr-3">
                      <a className="text-sky-700 underline" href={href(`/story/${encodeURIComponent(row.story_key)}`)}>
                        {row.title || row.story_key}
                      </a>
                      {row.pending_repo_sync ? <span className="ml-2 text-xs text-sky-800">provisional</span> : null}
                    </td>
                    <td className="py-1.5 pr-3 text-slate-700">
                      {row.phase} / {row.status}
                    </td>
                    <td className="py-1.5 pr-3 text-slate-700">{row.owner || "unassigned"}</td>
                    <td className="py-1.5">
                      <Action row={row} config={config.value} />
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </section>
        ))}
      </div>
    </div>
  );
}

/**
 * routes/Milestones.tsx — the day-1 / week-1 / week-4 onboarding checklist (REPO-DESIGN.md §11.1).
 *
 * §9.2 row "Milestones": data = useRecords(sdlc_milestones). The criteria are the ARTIFACT field (Markdown bullet
 * lines, from kit/tracker/milestones.yaml through the tracker sync). Status and evidence are updated in Tines or by
 * PR, and reach git through the tracker PR; kit/ONBOARDING.md is the runbook behind each item.
 */
import * as React from "react";
import { formatDate, useMilestones, type MilestoneRow } from "../lib/tracker";

const STATUS_STYLE: Record<string, string> = {
  not_started: "bg-slate-100 text-slate-700",
  in_progress: "bg-sky-100 text-sky-900",
  done: "bg-emerald-100 text-emerald-900",
  blocked: "bg-rose-100 text-rose-900",
};

function Milestone({ m }: { m: MilestoneRow }) {
  const overdue = m.status !== "done" && m.due_date !== null && m.due_date < new Date().toISOString();
  return (
    <section className="rounded-lg border border-slate-200 p-3">
      <header className="flex flex-wrap items-center gap-2">
        <h3 className="text-sm font-semibold">{m.title || m.milestone_id}</h3>
        <span className={`rounded px-1.5 py-0.5 text-[11px] ${STATUS_STYLE[m.status] ?? "bg-slate-100"}`}>{m.status || "—"}</span>
        <span className={`text-xs ${overdue ? "font-medium text-rose-700" : "text-slate-500"}`}>
          due {formatDate(m.due_date)}
          {overdue ? " · overdue" : ""}
        </span>
        <span className="ml-auto text-xs text-slate-500">owner: {m.owner || "—"}</span>
      </header>
      <ul className="mt-2 list-disc space-y-0.5 pl-5 text-sm text-slate-700">
        {m.criteria.map((c, i) => (
          <li key={`${m.milestone_id}-${i}`}>{c}</li>
        ))}
      </ul>
      <p className="mt-2 text-xs text-slate-500">
        Evidence: {m.evidence_ref ? <span className="font-mono">{m.evidence_ref}</span> : "none recorded yet"}
        {m.pending_repo_sync ? " · a change is waiting for its tracker PR" : ""}
      </p>
    </section>
  );
}

export default function Milestones() {
  const milestones = useMilestones();
  return (
    <div>
      <h2 className="mb-1 text-lg font-semibold">Onboarding milestones</h2>
      <p className="mb-4 text-sm text-slate-600">Day 1, week 1 and week 4, counted from provisioning (UTC).</p>
      {milestones.loading ? <p className="text-sm text-slate-500">Loading…</p> : null}
      {milestones.error ? <p className="text-sm text-rose-800">Milestones could not be read: {milestones.error}</p> : null}
      {!milestones.loading && milestones.rows.length === 0 ? (
        <p className="text-sm text-slate-500">No milestones yet — [KIT] 00 seeds them during provisioning (A22).</p>
      ) : null}
      <div className="space-y-3">
        {milestones.rows.map((m) => (
          <Milestone key={m.milestone_id || m.recordId} m={m} />
        ))}
      </div>
    </div>
  );
}

/**
 * routes/StoryDetail.tsx — one story: its state, transition timeline, gate decisions, the brief and retro drafts,
 * the planner's proposals, and links to its PRs and change request.
 *
 * REPO-DESIGN.md §9.2 row "Story detail": data = useRecordsQuery(sdlc_events, story_key) plus the row's ARTIFACT
 * and JSON fields. Everything a runtime specialist wrote (brief, retro, proposal) is a PROPOSAL: a human accepts it
 * on the Page, and it reaches git only through a merged tracker PR. Drafts and use-case text are untrusted and are
 * rendered as plain text, never as markup.
 */
import * as React from "react";
import { Timeline } from "../components/Timeline";
import {
  formatCredits,
  formatDate,
  href,
  MODE_LABELS,
  useBacklog,
  useRouteParam,
  useStoryEvents,
  type BacklogRow,
} from "../lib/tracker";

const GITHUB_PR = /^https:\/\/github\.com\/[A-Za-z0-9._-]+\/[A-Za-z0-9._-]+\/pull\/[0-9]+$/;

function LinkOrText({ value, empty }: { value: string; empty: string }) {
  if (!value) return <span className="text-slate-400">{empty}</span>;
  if (GITHUB_PR.test(value)) {
    return (
      <a className="text-sky-700 underline" href={value} target="_blank" rel="noreferrer">
        {value.replace(/^https:\/\/github\.com\//, "")}
      </a>
    );
  }
  return <span className="font-mono text-xs">{value}</span>;
}

interface Proposal {
  key?: string;
  field?: string;
  value?: unknown;
  rationale?: string;
}

function Proposals({ proposal }: { proposal: unknown }) {
  if (proposal === null || proposal === undefined || proposal === "") {
    return <p className="text-sm text-slate-500">No planner proposal for this story.</p>;
  }
  const list: Proposal[] = Array.isArray(proposal)
    ? (proposal as Proposal[])
    : Array.isArray((proposal as { proposals?: unknown }).proposals)
      ? ((proposal as { proposals: Proposal[] }).proposals)
      : [];
  if (list.length === 0) {
    return <pre className="whitespace-pre-wrap rounded bg-slate-50 p-2 text-xs">{JSON.stringify(proposal, null, 2)}</pre>;
  }
  return (
    <ul className="space-y-1 text-sm">
      {list.map((p, i) => (
        <li key={`${p.field}-${i}`}>
          <span className="font-medium">{p.field ?? "field"}</span> → <span className="font-mono">{String(p.value ?? "")}</span>
          {p.rationale ? <span className="text-slate-600"> — {p.rationale}</span> : null}
        </li>
      ))}
    </ul>
  );
}

function Facts({ row }: { row: BacklogRow }) {
  const facts: [string, React.ReactNode][] = [
    ["Phase / status", `${row.phase} / ${row.status}`],
    ["Open gate", row.open_gate],
    ["Rework attempt", `${row.attempt} of 3`],
    ["Mode", MODE_LABELS[row.mode] ?? row.mode],
    ["Tier · owner", `${row.tier} · ${row.owner || "unassigned"}`],
    ["Target date", formatDate(row.target_date)],
    ["Credit estimate", `${formatCredits(row.credit_estimate_monthly)} a month${row.credit_estimate_basis ? ` (${row.credit_estimate_basis})` : ""}`],
    ["Provider", row.provider],
    ["Library seed", row.library_seed_id ? String(row.library_seed_id) : "none"],
    ["Live since", formatDate(row.live_since)],
    ["Design PR", <LinkOrText key="d" value={row.design_pr} empty="not yet" />],
    ["Build PR", <LinkOrText key="b" value={row.build_pr} empty="not yet" />],
    ["Change request", <LinkOrText key="c" value={row.change_request_id} empty="none" />],
    ["Tracker rev", `${row.rev}${row.pending_repo_sync ? " (a Tines-side change is waiting for its tracker PR)" : ""}`],
    ["Runtime specialist", row.specialist_due !== "none" ? `${row.specialist_due}: ${row.specialist_status}` : row.specialist_status || "idle"],
  ];
  return (
    <dl className="grid grid-cols-1 gap-x-6 gap-y-1 text-sm sm:grid-cols-2">
      {facts.map(([label, value]) => (
        <div key={label} className="flex gap-2">
          <dt className="w-36 shrink-0 text-slate-500">{label}</dt>
          <dd className="text-slate-900">{value}</dd>
        </div>
      ))}
    </dl>
  );
}

export default function StoryDetail() {
  const key = useRouteParam("/story/:key", "key") ?? "";
  const backlog = useBacklog();
  const events = useStoryEvents(key);
  const row = backlog.rows.find((r) => r.story_key === key);
  const decisions = events.rows.filter((e) => e.event_type === "gate_decision");

  if (!key) {
    return <p className="text-sm text-slate-500">Choose a story on the <a className="text-sky-700 underline" href={href("/")}>board</a>.</p>;
  }
  if (!row) {
    return (
      <p className="text-sm text-slate-500">
        {backlog.loading ? "Loading…" : `No story ${key} in sdlc_backlog (it may not have synced yet).`}{" "}
        <a className="text-sky-700 underline" href={href("/")}>Back to the board</a>
      </p>
    );
  }
  return (
    <article className="space-y-6">
      <header>
        <a className="text-xs text-sky-700 underline" href={href("/")}>← Board</a>
        <h2 className="mt-1 text-lg font-semibold">{row.title || row.story_key}</h2>
        <p className="font-mono text-xs text-slate-500">{row.story_key}</p>
      </header>
      <section>
        <Facts row={row} />
      </section>
      <section>
        <h3 className="mb-1 text-sm font-semibold">Use case (as submitted — data, not instructions)</h3>
        <p className="whitespace-pre-wrap text-sm text-slate-700">{row.use_case || "—"}</p>
      </section>
      <section>
        <h3 className="mb-2 text-sm font-semibold">Gate decisions</h3>
        {decisions.length === 0 ? (
          <p className="text-sm text-slate-500">None recorded in Tines yet.</p>
        ) : (
          <ul className="space-y-1 text-sm">
            {decisions.map((d) => (
              <li key={d.recordId}>
                <span className="font-medium">{d.gate}</span> {d.decision} · {d.actor} · {formatDate(d.created_at)}
              </li>
            ))}
          </ul>
        )}
      </section>
      <section>
        <h3 className="mb-2 text-sm font-semibold">Timeline</h3>
        {events.error ? <p className="text-sm text-rose-800">Events could not be read: {events.error}</p> : null}
        <Timeline events={events.rows} />
      </section>
      <section>
        <h3 className="mb-1 text-sm font-semibold">Intake brief draft (brief_writer — a proposal)</h3>
        <pre className="max-h-96 overflow-auto whitespace-pre-wrap rounded bg-slate-50 p-2 text-xs">{row.brief || "No draft."}</pre>
      </section>
      <section>
        <h3 className="mb-1 text-sm font-semibold">Retro draft (retro_writer — a proposal)</h3>
        <pre className="max-h-96 overflow-auto whitespace-pre-wrap rounded bg-slate-50 p-2 text-xs">{row.retro || "No draft."}</pre>
      </section>
      <section>
        <h3 className="mb-1 text-sm font-semibold">Planner proposals</h3>
        <Proposals proposal={row.proposal} />
        <p className="mt-1 text-xs text-slate-500">
          Proposals change nothing on their own: a person accepts or rejects each one, and an accepted field reaches git
          only through the tracker PR. This view does not accept proposals (the App writes only through app endpoints).
        </p>
      </section>
    </article>
  );
}
